      pistas: ['<code>resultado = dict(producto)</code> copia el diccionario.', '<code>resultado["valor_stock"] = producto["precio"] * producto["stock"]</code>', '<code>resultado["marca"] = producto.get("marca", "sin marca")</code>'],
