      criterios: ['<code>resultado</code> es una lista de 3 nombres', 'Del más caro al más barato'], previo: 'productos = [\n    {"nombre": "Mouse", "precio": 25.5},\n    {"nombre": "Notebook", "precio": 899.0},\n    {"nombre": "Monitor", "precio": 210.0},\n    {"nombre": "Teclado", "precio": 45.0},\n    {"nombre": "Silla", "precio": 350.0},\n]', practica: ['python-listas', 'python-funciones'], ordenado: true,
