  // ================================================================== dbt
  const D = ['🌱 1 · Primeros modelos'];
  const DBT = [
    { id: 'dbz-1', campana: D[0], titulo: 'Tu primer modelo', nivel: 'Básico', de,
      pedido: 'Escribe un modelo que lea <b>toda</b> la tabla cruda <code>categorias</code> de la fuente <code>tienda</code>.' +
        saber(['<b>dbt</b> (data build tool) organiza las transformaciones de un data warehouse: cada <b>modelo</b> es un archivo <code>.sql</code> con <b>un solo SELECT</b>, y dbt se encarga de crear la vista o tabla con ese resultado.', 'Las tablas crudas que llegan de los sistemas se declaran como <b>sources</b> y se leen con <code>{{ source(\'tienda\', \'categorias\') }}</code>, nunca escribiendo su nombre a mano.', 'Lo que está entre <code>{{ }}</code> es <b>Jinja</b>: dbt lo reemplaza por el nombre real de la tabla al <b>compilar</b>. Abajo del resultado verás el SQL compilado.']),
      criterios: ["Usa <code>{{ source('tienda', 'categorias') }}</code>", 'Todas las columnas y filas'], tablas: ['categorias'], practica: ['dbt-sources-capas'],
      requiere: [["source\\(\\s*['\"]tienda['\"]\\s*,\\s*['\"]categorias['\"]\\s*\\)", "Lee la tabla con {{ source('tienda', 'categorias') }}."]],
      pistas: ['Un SELECT * común.', 'En el FROM va la función source entre llaves dobles.', "<code>select * from {{ source('tienda', 'categorias') }}</code>"],
      solucion: "select *\nfrom {{ source('tienda', 'categorias') }}" },
    { id: 'dbz-2', campana: D[0], titulo: 'Un modelo de staging', nivel: 'Básico', de: 'Tu líder técnico',
      pedido: 'Crea el staging de productos: columnas <code>producto_id</code>, <code>producto</code> (el nombre), <code>marca</code>, <code>precio</code> y <code>esta_activo</code> (verdadero si <code>activo = 1</code>).' +
        saber(['Un proyecto dbt se ordena en <b>capas</b>: <b>staging</b> (una por tabla cruda: renombrar, tipar y limpiar lo mínimo), <b>intermediate</b> (lógica de negocio) y <b>marts</b> (las tablas que consume el negocio).', 'En staging no se filtra ni se agrupa: se deja cada fila, con nombres claros y consistentes.', 'Una comparación como <code>activo = 1</code> devuelve verdadero o falso (en SQLite, 1 o 0): sirve para crear una columna booleana.']),
      criterios: ["Usa <code>{{ source('tienda', 'productos') }}</code>", 'Columnas: producto_id, producto, marca, precio, esta_activo', 'Todas las filas'], tablas: ['productos'], practica: ['dbt-sources-capas'],
      requiere: [["source\\(\\s*['\"]tienda['\"]\\s*,\\s*['\"]productos['\"]\\s*\\)", "Lee la tabla cruda con {{ source('tienda', 'productos') }}."]],
      pistas: ['<code>nombre as producto</code> renombra.', '<code>activo = 1 as esta_activo</code> crea la columna booleana.', "El FROM: <code>{{ source('tienda', 'productos') }}</code>."],
      solucion: "select\n    producto_id,\n    nombre as producto,\n    marca,\n    precio,\n    activo = 1 as esta_activo\nfrom {{ source('tienda', 'productos') }}" },
    { id: 'dbz-3', campana: D[0], titulo: 'Construir sobre otro modelo: ref', nivel: 'Básico', de: 'Operaciones',
      pedido: 'Usando el modelo <code>stg_pedidos</code> (ya existe en el proyecto), cuenta los pedidos por <code>canal</code>: columnas <code>canal</code> y <code>pedidos</code>.' +
        saber(['<code>{{ ref(\'stg_pedidos\') }}</code> lee <b>otro modelo</b> del proyecto. Es la pieza más importante de dbt.', 'Con ref, dbt sabe que tu modelo <b>depende</b> de stg_pedidos: arma el grafo de dependencias (el <b>linaje</b>) y construye los modelos en el orden correcto.', 'Regla: source() solo en staging; en todo lo demás, ref().']),
      criterios: ["Usa <code>{{ ref('stg_pedidos') }}</code>", 'Columnas: canal, pedidos', 'Una fila por canal'], tablas: ['pedidos'], practica: ['dbt-modelos-ref'],
      requiere: [["ref\\(\\s*['\"]stg_pedidos['\"]\\s*\\)", "Lee los pedidos con {{ ref('stg_pedidos') }}."]],
      pistas: ['Es un GROUP BY común.', "El FROM es <code>{{ ref('stg_pedidos') }}</code>.", "<code>select canal, count(*) as pedidos from {{ ref('stg_pedidos') }} group by canal</code>"],
      solucion: "select\n    canal,\n    count(*) as pedidos\nfrom {{ ref('stg_pedidos') }}\ngroup by canal" },
    { id: 'dbz-4', campana: D[0], titulo: 'El estilo de dbt: CTEs de importación', nivel: 'Intermedio', de: 'Tu líder técnico',
      pedido: 'Cada cliente con su cantidad de pedidos (también los que tienen 0): columnas <code>cliente_id</code>, <code>nombre_completo</code> y <code>pedidos</code>. Usa <code>stg_clientes</code> y <code>stg_pedidos</code>, con el estilo de CTEs de dbt.' +
        saber(['El estilo recomendado por dbt: arriba, una CTE de "importación" por cada modelo que lees (<code>with clientes as (select * from {{ ref(\'stg_clientes\') }})</code>); después, CTEs con la lógica; al final, <code>select * from final</code>.', 'Así se ve de un vistazo de qué depende el modelo, y cada paso se puede probar por separado.', 'Para incluir a los clientes sin pedidos: LEFT JOIN y <code>count(p.pedido_id)</code> (COUNT de una columna no cuenta los NULL, así que da 0).']),
      criterios: ["Usa <code>ref('stg_clientes')</code> y <code>ref('stg_pedidos')</code>", 'Columnas: cliente_id, nombre_completo, pedidos', 'Todos los clientes, con 0 si no tienen pedidos'], tablas: ['clientes', 'pedidos'], practica: ['dbt-modelos-ref'],
      requiere: [["ref\\(\\s*['\"]stg_clientes['\"]\\s*\\)", "Lee los clientes con {{ ref('stg_clientes') }}."], ["ref\\(\\s*['\"]stg_pedidos['\"]\\s*\\)", "Lee los pedidos con {{ ref('stg_pedidos') }}."], ['^\\s*with\\b', 'Usa el estilo de CTEs: empieza con with.']],
      pistas: ["<code>with clientes as (select * from {{ ref('stg_clientes') }}), pedidos as (select * from {{ ref('stg_pedidos') }}),</code>", '<code>final as (select c.cliente_id, c.nombre_completo, count(p.pedido_id) as pedidos from clientes c left join pedidos p on p.cliente_id = c.cliente_id group by c.cliente_id, c.nombre_completo)</code>', 'Y al final <code>select * from final</code>.'],
      solucion: "with clientes as (\n    select * from {{ ref('stg_clientes') }}\n),\n\npedidos as (\n    select * from {{ ref('stg_pedidos') }}\n),\n\nfinal as (\n    select\n        c.cliente_id,\n        c.nombre_completo,\n        count(p.pedido_id) as pedidos\n    from clientes c\n    left join pedidos p on p.cliente_id = c.cliente_id\n    group by c.cliente_id, c.nombre_completo\n)\n\nselect * from final" },
    { id: 'dbz-5', campana: D[0], titulo: 'Jinja: escribir SQL con un bucle', nivel: 'Intermedio', de: 'Operaciones',
      pedido: 'Por <code>canal</code>, una columna con la cantidad de pedidos de cada estado: <code>entregado</code>, <code>enviado</code>, <code>pendiente</code>, <code>cancelado</code> y <code>devuelto</code>. Genera las columnas con un <code>{% for %}</code> en vez de escribirlas a mano.' +
        saber(['<code>{% set estados = [\'entregado\', \'enviado\'] %}</code> guarda una lista de Jinja.', '<code>{% for e in estados %} … {% endfor %}</code> repite el SQL de adentro una vez por cada elemento: dbt <b>escribe código por ti</b>.', 'Para contar con condición: <code>sum(case when estado = \'{{ e }}\' then 1 else 0 end) as {{ e }}</code>.', 'Cuidado con la última coma: <code>{% if not loop.last %},{% endif %}</code> la pone en todas menos la última. Mira el SQL compilado para ver lo que generó el bucle.']),
      criterios: ['Columnas: canal, entregado, enviado, pendiente, cancelado, devuelto', 'Una fila por canal', 'Las columnas se generan con un <code>{% for %}</code>'], tablas: ['pedidos'], practica: ['dbt-jinja-macros'],
      requiere: [['\\{%-?\\s*for\\b', 'Genera las columnas con un {% for %}.'], ["ref\\(\\s*['\"]stg_pedidos['\"]\\s*\\)", "Lee los pedidos con {{ ref('stg_pedidos') }}."]],
      pistas: ["<code>{% set estados = ['entregado', 'enviado', 'pendiente', 'cancelado', 'devuelto'] %}</code>", "Dentro del select: <code>{% for e in estados %} sum(case when estado = '{{ e }}' then 1 else 0 end) as {{ e }}{% if not loop.last %},{% endif %} {% endfor %}</code>", "Antes del bucle va <code>canal,</code> y después <code>from {{ ref('stg_pedidos') }} group by canal</code>."],
      solucion: "{% set estados = ['entregado', 'enviado', 'pendiente', 'cancelado', 'devuelto'] %}\n\nselect\n    canal,\n    {% for e in estados %}\n    sum(case when estado = '{{ e }}' then 1 else 0 end) as {{ e }}{% if not loop.last %},{% endif %}\n    {% endfor %}\nfrom {{ ref('stg_pedidos') }}\ngroup by canal" },
  ];
