      test: 'd = dags.get("comandos")\nassert d is not None, "No encontré el DAG comandos"\nt = d.get_task("listar")\nassert type(t).__name__ == "BashOperator", "listar debe ser un BashOperator (es %s)" % type(t).__name__\nassert t.bash_command.strip() == "ls -la /tmp", "El comando debe ser ls -la /tmp (es %r)" % t.bash_command',
